"""Part 3: findings with verbatim evidence quotes (<=40 words each). Quotes are copied from the page text saved by fetch.py."""

def f(claim, source, conf, quote="", value=""):
    d = {"claim": claim, "source": source, "confidence": conf}
    if value: d["value"] = value
    d["evidence_quote"] = quote
    return d

